			builder.path(path);
			builder.query(query);
		}
		if (StringUtils.hasText(fragment)) {
			builder.fragment(fragment);
		}
		return builder;
	}
	else {
		throw new IllegalArgumentException("[" + uri + "] is not a valid URI");
	}
}

